insert into biblioteca (titulo, categoria, contenido, fuente, activo) values
  ('El Sol ☉', 'Planetas', 'Tu identidad central, tu ego y tu vitalidad. El Sol representa quién eres en tu esencia más pura: tu propósito, tu voluntad y la energía que te hace brillar. El signo donde está tu Sol describe tu forma natural de expresarte y lo que necesitas para sentirte vivo. No es toda tu personalidad (eso lo dice la carta completa), pero sí es el núcleo alrededor del cual gira todo lo demás.', 'Sam Alquimia Astral', true),
  ('La Luna ☽', 'Planetas', 'Tus emociones, tu mundo interior y lo que necesitas para sentirte segura. La Luna representa tus reacciones instintivas, tus hábitos emocionales y la forma en que buscas consuelo. Mientras el Sol es quién quieres ser, la Luna es quién eres cuando nadie te está viendo. Conocer tu signo lunar te ayuda a entender qué necesitas de verdad para sentirte en calma.', 'Sam Alquimia Astral', true),
  ('Mercurio ☿', 'Planetas', 'Cómo piensas, hablas y procesas información. Mercurio rige la comunicación, el aprendizaje y la manera en que conectas ideas. El signo de tu Mercurio natal describe tu estilo mental: si eres más rápida o reflexiva, directa o diplomática, lógica o intuitiva al comunicarte.', 'Sam Alquimia Astral', true),
  ('Venus ♀', 'Planetas', 'El amor, la belleza y lo que valoras. Venus describe cómo amas, qué te atrae, y tu relación con el placer, el dinero y la estética. Tu Venus natal es clave para entender tu forma de vincularte en pareja y qué te hace sentir apreciada.', 'Sam Alquimia Astral', true),
  ('Marte ♂', 'Planetas', 'Tu energía, tu deseo y cómo actúas ante un conflicto o un reto. Marte es el planeta de la acción, la ambición y la pasión. Su posición en tu carta muestra cómo persigues lo que quieres, cómo te defiendes, y dónde tienes más impulso natural.', 'Sam Alquimia Astral', true),
  ('Júpiter ♃', 'Planetas', 'Expansión, suerte y crecimiento. Júpiter es el planeta más generoso del zodiaco: marca en qué áreas de tu vida tiendes a tener abundancia, optimismo y oportunidades. También señala hacia dónde te conviene crecer y confiar más en ti misma.', 'Sam Alquimia Astral', true),
  ('Saturno ♄', 'Planetas', 'Estructura, responsabilidad y las lecciones que más maduran. Saturno no es un planeta "malo" — es el maestro exigente que te enseña disciplina y te da resultados sólidos con el tiempo, aunque a veces con esfuerzo. Su posición muestra dónde tienes que trabajar más duro, y también dónde puedes construir algo duradero.', 'Sam Alquimia Astral', true),
  ('Urano ♅', 'Planetas', 'Cambio, originalidad y ruptura de reglas. Urano rige lo inesperado, la rebeldía y tu forma única de ser distinta a los demás. Su posición en tu carta habla de dónde necesitas libertad y dónde tiendes a romper con lo convencional.', 'Sam Alquimia Astral', true),
  ('Neptuno ♆', 'Planetas', 'Intuición, espiritualidad y los sueños. Neptuno rige la imaginación, la compasión y también la ilusión o la confusión. Su posición muestra en qué área de tu vida eres más sensible, más soñadora, y a veces más propensa a idealizar.', 'Sam Alquimia Astral', true),
  ('Plutón ♇', 'Planetas', 'Transformación profunda y poder. Plutón representa los procesos de muerte y renacimiento simbólico: lo que se destruye para dar paso a algo más auténtico. Su posición señala en qué área de tu vida vives tus transformaciones más intensas.', 'Sam Alquimia Astral', true),
  ('Casa 1 — Identidad', 'Casas', 'La casa de tu Ascendente: cómo te presentas al mundo, tu apariencia y tu primera impresión. Es tu "portada", la energía con la que arrancas cualquier situación nueva.', 'Sam Alquimia Astral', true),
  ('Casa 2 — Recursos y valores', 'Casas', 'Tu relación con el dinero, las posesiones y tu autoestima. Describe cómo generas seguridad material y qué es lo que realmente valoras en la vida.', 'Sam Alquimia Astral', true),
  ('Casa 3 — Comunicación', 'Casas', 'Cómo piensas, hablas, aprendes y te relacionas con tu entorno cercano (hermanos, vecinos, trayectos cortos). Rige también los estudios básicos y la curiosidad diaria.', 'Sam Alquimia Astral', true),
  ('Casa 4 — Hogar y raíces', 'Casas', 'Tu familia, tu infancia y tu sentido de pertenencia. Es la base emocional desde la que construyes todo lo demás, y también representa el final de los ciclos.', 'Sam Alquimia Astral', true),
  ('Casa 5 — Creatividad y placer', 'Casas', 'Romance, creatividad, hijos y todo lo que haces por puro disfrute. Es la casa del juego, la expresión artística y el corazón abierto.', 'Sam Alquimia Astral', true),
  ('Casa 6 — Trabajo y salud', 'Casas', 'Tus rutinas diarias, tu salud física y tu forma de servir a otros. Habla de cómo organizas tu día a día y qué tan bien cuidas de ti misma.', 'Sam Alquimia Astral', true),
  ('Casa 7 — Relaciones', 'Casas', 'Pareja, sociedades y contratos formales. Es el espejo de cómo te vinculas con "el otro" y qué buscas en una relación de igual a igual.', 'Sam Alquimia Astral', true),
  ('Casa 8 — Transformación', 'Casas', 'Intimidad profunda, recursos compartidos, y los procesos de crisis y renacimiento. Es una de las casas más intensas: habla de lo que se transforma cuando sueltas el control.', 'Sam Alquimia Astral', true),
  ('Casa 9 — Expansión', 'Casas', 'Viajes largos, filosofía, estudios superiores y tu búsqueda de sentido. Es la casa que te empuja a ampliar tu visión del mundo, física o mentalmente.', 'Sam Alquimia Astral', true),
  ('Casa 10 — Vocación', 'Casas', 'Tu carrera, tu reputación pública y tu lugar en la sociedad. Es donde se ve tu ambición y el legado que quieres dejar.', 'Sam Alquimia Astral', true),
  ('Casa 11 — Comunidad', 'Casas', 'Amistades, grupos y proyectos colectivos. Representa tus esperanzas a futuro y las personas con las que compartes una visión.', 'Sam Alquimia Astral', true),
  ('Casa 12 — Lo oculto', 'Casas', 'El inconsciente, el descanso, lo espiritual y lo que trabajamos en soledad. Es la casa más introspectiva, ligada a la sanación y al cierre de ciclos kármicos.', 'Sam Alquimia Astral', true),
  ('Elemento Fuego 🔥 (Aries, Leo, Sagitario)', 'Elementos', 'Acción, pasión y espontaneidad. Los signos de fuego se mueven por impulso, entusiasmo y una necesidad genuina de vivir intensamente. Su reto es aprender paciencia; su regalo es contagiar energía y valentía a quienes los rodean.', 'Sam Alquimia Astral', true),
  ('Elemento Tierra 🌿 (Tauro, Virgo, Capricornio)', 'Elementos', 'Estabilidad, practicidad y constancia. Los signos de tierra construyen resultados tangibles y confían en lo que pueden tocar y comprobar. Su reto es soltar el control; su regalo es la capacidad de sostener lo que otros apenas sueñan.', 'Sam Alquimia Astral', true),
  ('Elemento Aire 🌬️ (Géminis, Libra, Acuario)', 'Elementos', 'Ideas, comunicación y conexión social. Los signos de aire viven en el mundo de los conceptos, las relaciones y el intercambio de perspectivas. Su reto es aterrizar sus ideas en acciones concretas; su regalo es la claridad mental y la capacidad de conectar a las personas.', 'Sam Alquimia Astral', true),
  ('Elemento Agua 💧 (Cáncer, Escorpio, Piscis)', 'Elementos', 'Emoción, intuición y sensibilidad profunda. Los signos de agua sienten antes de pensar y perciben lo que no se dice. Su reto es poner límites emocionales; su regalo es una empatía y una profundidad que sanan a quienes están cerca.', 'Sam Alquimia Astral', true),
  ('Luna Nueva 🌑', 'Fases Lunares', 'El inicio del ciclo. La Luna Nueva es momento de sembrar intenciones, empezar proyectos y poner en palabras lo que quieres atraer. Es una energía introspectiva: antes de actuar hacia afuera, toca decidir hacia dónde quieres ir.', 'Sam Alquimia Astral', true),
  ('Luna Creciente 🌒', 'Fases Lunares', 'Construcción y decisión. Después de sembrar la intención en Luna Nueva, esta fase pide acción concreta: los primeros pasos, superar dudas iniciales y comprometerte con lo que empezaste.', 'Sam Alquimia Astral', true),
  ('Cuarto Creciente 🌓', 'Fases Lunares', 'Tensión productiva. Suelen aparecer los primeros obstáculos reales. Es momento de ajustar el plan, no de abandonarlo — la fricción de esta fase fortalece lo que estás construyendo.', 'Sam Alquimia Astral', true),
  ('Luna Gibosa Creciente 🌔', 'Fases Lunares', 'Refinamiento. Estás cerca de la meta: toca pulir detalles, ajustar lo que no está funcionando del todo y prepararte para el punto máximo del ciclo.', 'Sam Alquimia Astral', true),
  ('Luna Llena 🌕', 'Fases Lunares', 'Culminación y claridad. La Luna Llena ilumina lo que estaba oculto: resultados, revelaciones y emociones intensificadas. Es el punto de mayor energía del mes, ideal para celebrar lo logrado o soltar lo que ya no sirve.', 'Sam Alquimia Astral', true),
  ('Luna Gibosa Menguante 🌖', 'Fases Lunares', 'Gratitud y distribución. Después del punto máximo, toca compartir lo aprendido, agradecer y empezar a soltar lo que ya cumplió su propósito.', 'Sam Alquimia Astral', true),
  ('Cuarto Menguante 🌗', 'Fases Lunares', 'Liberación. Esta fase pide soltar activamente: hábitos, relaciones o pensamientos que ya no te representan. Es un momento de limpieza antes de cerrar el ciclo.', 'Sam Alquimia Astral', true),
  ('Luna Balsámica 🌘', 'Fases Lunares', 'Descanso y cierre. La fase final antes de la Luna Nueva siguiente. Es momento de descansar, reflexionar sobre el ciclo que termina, y prepararte —sin prisa— para sembrar algo nuevo.', 'Sam Alquimia Astral', true);